"""Build a shareable offline research dashboard from verified result JSON."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parent

def main():
    broad=json.loads((ROOT/'full_event_study_results.json').read_text())
    selected=json.loads((ROOT/'event_risk_results.json').read_text())
    claims=json.loads((ROOT/'claim_pilot_results.json').read_text())
    body=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Macro Evidence Lab · Pakistan FX decision audit</title><style>
:root{--bg:#0b1320;--card:#162333;--muted:#a9bccc;--line:#314355;--accent:#67e8c2;--warn:#f2bf7d;--text:#f4f5f5}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 90% 4%,#21434a,var(--bg) 35%);color:var(--text);font:16px/1.55 system-ui,sans-serif}main{max-width:1150px;margin:auto;padding:36px 22px 88px}h1,h2,h3{line-height:1.14;letter-spacing:-.04em}h1{font-size:clamp(2.7rem,6vw,5rem);max-width:800px;margin:15px 0}h2{font-size:clamp(1.7rem,3vw,2.4rem)}h3{font-size:1.15rem}p{margin:12px 0 18px}a{color:var(--accent)}.kicker{text-transform:uppercase;letter-spacing:.16em;color:var(--accent);font-weight:700;font-size:.76rem}.lead{color:var(--muted);font-size:1.1rem;max-width:820px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:30px 0}.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:22px}.metric{font-size:2.4rem;letter-spacing:-.06em;font-weight:750;line-height:1.15;color:var(--accent)}.small{color:var(--muted);font-size:.88rem}.callout{border-left:4px solid var(--warn);padding:8px 20px;background:#1f2a35;border-radius:0 12px 12px 0;margin:24px 0}.row{display:flex;justify-content:space-between;gap:10px;align-items:center}.bar{height:17px;background:#314355;border-radius:20px;overflow:hidden}.bar>i{display:block;height:100%;background:var(--accent);border-radius:20px}.bar.warm>i{background:var(--warn)}.year{margin:22px 0 31px}.year small{color:var(--muted)}.box{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:26px;margin:22px 0}.cols{display:grid;grid-template-columns:1fr 1fr;gap:20px}.pill{background:#244037;border-radius:6px;color:var(--accent);padding:5px 9px;font-size:.82rem;font-weight:700}button{background:var(--accent);border:0;color:#09271b;padding:12px 15px;border-radius:8px;font-weight:700;cursor:pointer}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid var(--warn);outline-offset:3px}select{background:var(--card);color:var(--text);border:1px solid var(--line);padding:11px;border-radius:8px;font:inherit}table{border-collapse:collapse;width:100%;font-size:.92rem}th,td{padding:12px;border-bottom:1px solid var(--line);text-align:left}td.num,th.num{text-align:right}table a{white-space:nowrap}.scroll{overflow:auto}.danger{color:var(--warn)}footer{border-top:1px solid var(--line);color:var(--muted);font-size:.82rem;padding-top:20px;margin-top:35px}@media(max-width:800px){.grid,.cols{grid-template-columns:1fr}main{padding:23px 14px 60px}.card,.box{padding:17px}}
</style></head><body><main><div class="kicker">Independent macro research · Pakistan 2021–2025</div><h1>Would five crisis cases fool your risk model?</h1><p class="lead">Five carefully chosen policy days made USD/PKR moves look exceptional. We widened the test to every listed SBP policy statement in five years, then checked a later year separately. The difference shrank sharply. Explore the calculation and the cases behind it.</p><div class="grid"><div class="card"><div class="metric">40</div><div>policy statements, 2021–2025</div></div><div class="card"><div class="metric">+0.70 pp</div><div>development-year average event versus control difference</div></div><div class="card"><div class="metric">+0.05 pp</div><div>same difference in the 2025 holdout year</div></div></div><div class="callout"><strong>The research result:</strong> five selected crisis cases averaged a 7.80% maximum 20-observation FX reference move, versus 5.14% across <em>all 17</em> 2022–2023 policy statements. The small 2025 difference cautions against a general policy-day risk claim. This is observational and uses nontradable reference prices.</div>
<section class="box"><div class="kicker">Year by year · primary outcome</div><h2>Maximum absolute 20-observation USD/PKR move</h2><p class="small">Green: mean following SBP statement dates. Amber: mean for same-year control starts away from policy meetings. Controls can overlap; their count is not an independent sample size.</p><div id="yearBars"></div><p class="small">Year 2025 was held out from the exploratory 2021–2024 comparison. The design was chosen after some 2022–2023 case history was known; even the holdout is only one year.</p></section>
<section class="box"><div class="kicker">Inspect the primary observations</div><h2>Policy-date reference windows</h2><label for="filter">Show year </label><select id="filter"><option value="all">All 40</option><option>2021</option><option>2022</option><option>2023</option><option>2024</option><option>2025</option></select><p class="small">The outcome starts with the first recorded FX observation strictly after each policy date and ends after 20 observations. No intraday trading or executable-price claim is made.</p><div class="scroll"><table><thead><tr><th>Policy date</th><th>FX window</th><th class="num">Final move</th><th class="num">Largest absolute move</th></tr></thead><tbody id="events"></tbody></table></div></section>
<section class="box"><div class="kicker">Sensitivity check · 5, 10, 20 observations</div><h2>Does the horizon change the answer?</h2><p class="small">Differences are percentage points: mean policy-date maximum move minus same-year mean control move. The exact two-sided sign-flip reference swaps signs of the five annual differences rather than treating overlapping daily windows as independent. Exchangeable year-level signs are an unverified assumption; 2025 alone cannot support a significance test.</p><div class="scroll"><table><thead><tr><th>Observations</th><th class="num">2021–2024 difference</th><th class="num">2025 difference</th><th class="num">Five-year sign-flip p</th></tr></thead><tbody>/*__SENSITIVITY__*/</tbody></table></div><p class="small">All three 2025 estimates are small. The 20-observation five-year reference p is 0.0625; with only five paired years, this does not prove the effect is zero or economically negligible. The shorter horizons were inspected after the 20-observation result: they are exploratory robustness checks.</p></section>
<section class="cols"><div class="box"><div class="kicker">Evidence checking · measured pilot</div><h2>Where the NLP baseline failed</h2><p>The TF-IDF fact retriever plus numeric/polarity checks scored <strong>25 of 30 related claims</strong> correctly and abstained three times. It wrongly accepted an August inflation claim of 38% because 38% appeared as a May peak in the same September 2023 statement: matching a number cannot establish its date.</p><p class="small">These claims are derived from 15 manually checked facts in five documents. They are not 30 independent examples or an LLM evaluation. A runner for an external local LLM is included; no LLM output is asserted.</p></div><div class="box"><div class="kicker">What an investor can conclude</div><h2>Source discipline beats a neat signal</h2><p>Different horizons can reverse a conclusion. After 7 April 2022, the 20-observation endpoint was −0.79%; by the eve of the next policy meeting the change was +6.97%. The five-case result was selected with hindsight; the broader sample provides a check on that choice.</p><p class="small">The script, source-linked dates, 3,170 historical reference observations, controls and failure logs are included in the project archive. The current work does not demonstrate a tradable FX edge or measure benefit to real users.</p></div></section>
<footer>Sources: <a href="https://www.sbp.org.pk/our-operations/publications/monetary-policy-statements/501" target="_blank" rel="noopener noreferrer">SBP policy statement catalogue</a> and <a href="https://archive.sbp.org.pk/ecodata/BFER_Daily_Arch.xlsx" target="_blank" rel="noopener noreferrer">SBP bank floating average FX archive</a>. Some SBP legacy links redirect unexpectedly; the project archive includes dated source references and reproducible calculations. Educational research only.</footer></main><script>
'use strict';const D=/*__DATA__*/;const $=s=>document.getElementById(s);function pct(x){return(x>=0?'+':'')+x.toFixed(2)+'%'}
let bars=$('yearBars');for(const year of Object.keys(D.years)){let s=D.years[year];const holder=document.createElement('div');holder.className='year';const header=document.createElement('div');header.className='row';const title=document.createElement('strong');title.textContent=year+(year==='2025'?' · HOLDOUT':'');const count=document.createElement('small');count.textContent=s.n_statements+' statements · '+s.n_control_anchors+' eligible control starts';header.append(title,count);holder.append(header);for(const [label,v,warm] of [['Policy dates',s.mean_statement_max_excursion_pct,false],['Controls',s.mean_control_max_excursion_pct,true]]){const row=document.createElement('div');row.className='row';row.append(document.createTextNode(label),document.createTextNode(v.toFixed(2)+'%'));holder.append(row);const bar=document.createElement('div');bar.className='bar'+(warm?' warm':'');bar.setAttribute('role','img');bar.setAttribute('aria-label',`${year} ${label} mean maximum change ${v.toFixed(2)} percent`);const inside=document.createElement('i');inside.style.width=(Math.min(100,v/6.5*100))+'%';bar.append(inside);holder.append(bar)}bars.append(holder)}
function events(){const yr=$('filter').value;const tbody=$('events');tbody.replaceChildren();for(const [year,s] of Object.entries(D.years)){if(yr!=='all'&&year!==yr)continue;for(const e of s.statement_outcomes){const row=document.createElement('tr');for(const value of [e.anchor,e.start+' → '+e.end,pct(e.endpoint_pct),Math.abs(e.max_abs_excursion_pct).toFixed(2)+'%']){const cell=document.createElement('td');cell.textContent=value;row.append(cell)}row.children[2].className='num';row.children[3].className='num';tbody.append(row)}}} $('filter').addEventListener('change',events);events();
</script></body></html>'''
    n2022_23=[e['max_abs_excursion_pct'] for year in ('2022','2023') for e in broad['year_results'][year]['statement_outcomes']]
    from statistics import mean
    assert round(mean(n2022_23),2)==5.14
    assert round(selected['mean_event_max_abs_pct'],2)==7.80
    assert claims['n']==30
    assert broad['statement_date_count']==40
    assert round(broad['development_mean_of_year_differences_pp'],2)==0.70
    assert round(broad['holdout_2025_difference_pp'],2)==0.05
    out=ROOT/'research_dashboard.html'
    rows=[]
    for h, v in broad['horizon_sensitivity'].items():
        rows.append(f"<tr><td>{h}</td><td class=\"num\">{v['development_mean_of_year_differences_pp']:+.3f} pp</td><td class=\"num\">{v['holdout_2025_difference_pp']:+.3f} pp</td><td class=\"num\">{v['all_year_sign_flip']['two_sided_p']:.4f}</td></tr>")
    html=body.replace('/*__SENSITIVITY__*/',''.join(rows))
    out.write_text(html.replace('/*__DATA__*/',json.dumps({'years':broad['year_results']}).replace('</','<\\/')),encoding='utf-8')
    print(out)

if __name__=='__main__':main()
